import { execFileSync } from 'node:child_process'
import { mkdir, writeFile } from 'node:fs/promises'

function buildVersion() {
  try {
    return execFileSync('git', ['rev-parse', '--short', 'HEAD'], { encoding: 'utf8' }).trim()
  } catch {
    return String(process.env.CF_PAGES_COMMIT_SHA || process.env.WORKERS_CI_COMMIT_SHA || 'unknown').trim() || 'unknown'
  }
}

const directory = new URL('../worker/generated/', import.meta.url)
await mkdir(directory, { recursive: true })
await writeFile(new URL('build-info.ts', directory), [
  '// Generated by scripts/build-worker-info.mjs. Do not edit.',
  `export const TOMIFY_VERSION = ${JSON.stringify(buildVersion())}`,
  'export const TOMIFY_AGENT_CONTRACT = 2',
  '',
].join('\n'))
